with cs_projects as (select id from public.projects where is_cs = true), cs_experts as (select distinct pe.expert_id from public.project_experts pe join cs_projects cp on cp.id = pe.project_id), duplicate_cs_assignments as (select pe.expert_id, count(distinct pe.project_id) as project_count from public.project_experts pe join cs_projects cp on cp.id = pe.project_id group by pe.expert_id having count(distinct pe.project_id) > 1)
select
  (select count(*) from public.projects) as all_projects,
  (select count(*) from public.experts) as all_experts,
  (select count(*) from cs_projects) as cs_projects,
  (select count(*) from cs_experts) as cs_experts,
  (select count(*) from public.project_locations where is_primary) as primary_project_locations,
  (select count(*) from public.projects p where not exists (select 1 from public.experts e where e.id = p.lead_expert_id)) as projects_without_existing_lead,
  (select count(*) from duplicate_cs_assignments) as cs_experts_assigned_to_multiple_projects,
  (select bool_and(project_count = 2) from duplicate_cs_assignments) as duplicated_cs_expert_has_two_projects;

